INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'zhCN', '宿命诱惑：初诞者圣墓', '', '', '', '', '', '', '', '', 45114),
(66694, 'zhCN', '宿命诱惑：统御圣所', '', '', '', '', '', '', '', '', 45114),
(66661, 'zhCN', '硬币的价值', '在奥利波斯寻找一名掮灵，从而获取信息。', '<这个奇特的物体提供了一些答案，但却带来了更多疑问。你是怎么得到它的？它有什么用？会不会有危险？>\n\n<如果连永恒之城都无法为你提供答案，那在此进行贸易的掮灵一定知道些什么。>', '', '', '', '', '', '', 45114),
(66649, 'zhCN', '扭转宿命之轮', '击败$1oa个不同的宿命团队副本首领。', '<尽管你经历过许多试练，但还是感觉到体内有股力量在增长。无论这些诡异的力量源自哪里，你现在从中感受到了宽慰而非困惑。>\n\n<再次投身未知。与黑暗抗争，用你的双手握住自己的宿命。>', '', '', '', '', '', '', 45114),
(66648, 'zhCN', '宿命交织', '击败30个不同的宿命团队副本首领。', '<现实在你周围旋转。你对于此处的记忆开始变得模糊，每过一秒回忆都在急速变幻。有什么事情发生了改变。>\n\n<你确信虽然一切似曾相识，但这里和你曾经知晓的那个地方并不相同。至少不完全相同。>\n\n<不管怎样，道路在你面前延展。无论是一场骗局还是时空的扭曲，它们都无法阻挠你的命运。>', '', '', '', '', '', '', 45114),
(66619, 'zhCN', '安特洛斯', '', '', '', '', '', '', '', '', 45114),
(66618, 'zhCN', '莫盖斯', '', '', '', '', '', '', '', '', 45114),
(66615, 'zhCN', '诺尔伽什·泥躯', '', '', '', '', '', '', '', '', 45114),
(65412, 'zhCN', '百思方得其解', '', '', '', '', '', '', '', '', 45114),
(65135, 'zhCN', '朋友的朋友：宗主艾莉奥瑟', '', '', '', '', '', '', '', '', 45114),
(65096, 'zhCN', '你死我获', '消灭惩戒者玛卡里斯，并收集$2oa个神圣圣物。', '我们从恒远碎片发现的圣物上获得了丰富的信息。\n\n但渊誓者注意到了我们的发现，想要阻挠我们。他们在那附近布下了重重陷阱，想阻止我们接近圣物。\n\n不能让典狱长切断我们与这些圣物的联系。\n\n请消除这些渊誓者造成的威胁，尽可能多地取回圣物。', '', '托加斯特的许多陷阱都是由他创造的，现在他开始将这些陷阱用在扎雷殁提斯。', '惩戒者玛卡里斯', '', '', '', 45114),
(64977, 'zhCN', '入场试炼', '击败具现枢纽中生成的造物。', '这片土地有许多超乎寻常的地方，即使它们源自上古，如今仍在适应、变化。万物都不是静止不变的。\n\n在具现枢纽的深处有一个锻炉，似乎能够对这些设计进行测试，还能学习。这些生物有朝一日也许会保护扎雷殁提斯，抵御外来的威胁，所以你应该尽量测试一下它们的强度。\n\n去吧，挑战锻炉的造物，再向我回报情况。', '', '', '', '', '', '', 45114),
(64579, 'zhCN', '空洞的价值', '使用菲历姆的锻炉阀门，从元尊锻炉处收集$1oa份残留的更迭微粒。', '散落在扎雷殁提斯各地的大型金属球体是用过的锻炉，它们在造物过程中遭到了废弃。\n\n这些空洞的金属躯壳里依然包含着残余的造物材料，或许能够为我们所用。\n\n在这些金属球体附近使用我的锻炉阀门，收集任何残留的更迭微粒。你也许还能找到其他有用的原型材料。', '', '', '', '', '', '', 45114),
(54688, 'zhCN', '审判官埃里克', '', '', '', '', '', '', '', '', 45114),
(54588, 'zhCN', '监工克里克斯', '', '', '', '', '', '', '', '', 45114),
(53317, 'zhCN', '高密度的雷银', '', '', '', '', '', '', '', '', 45114),
(44191, 'zhCN', '危险：卡萨克斯', '', '', '', '', '', '', '', '', 45114),
(43619, 'zhCN', '通缉：莎拉·魔息', '', '', '', '', '', '', '', '', 45114),
(41498, 'zhCN', '魔石蜥蜴', '', '', '', '', '', '', '', '', 45114),
(34530, 'zhCN', 'Shaper Dungeon [PH] Challenge Mode - Consolation (Nth)', '', '', '', '', '', '', '', '', 45114),
(33100, 'zhCN', '帝王之道', '击败玉珑、赤精、雪怒和砮皂这四位潘达利亚的至尊天神。', '不久前，潘达利亚的至尊天神给予了你一项挑战——而你取得了胜利。$b$b但你能在战斗中打败他们吗？他们在考验潘达利亚所有英雄的胆魄。$b$b这项挑战并非不可能完成，可你需要听取熊猫人末代皇帝的建议，并凭借坚定的内在力量应对这项挑战。你还需要集结一小支军队，去找些你信任的朋友来吧。$b$b在天神庭院击败四位天神，我们的旅途就差不多要结束了……', '', '', '', '', '', '', 45114),
(33088, 'zhCN', '永恒的发现', '前往位于翡翠林东南部的永恒岛，并与拉希奥交谈。', '潘达利亚。正当我以为自己已经洞悉了这片大陆上的一切神秘时，我却有了新的发现。$b$b那地方叫做“永恒岛”。它曾经深藏在迷雾之中，仿佛听凭自己的意志忽而出现，忽而消失。我听说时间在那里毫无意义，既无日出，也无日落。$b$b我们正好可以利用这一怪象，$n！如果我能用时间锁住你的斗篷，它所蕴含的力量将会是……无边无际的。$b$b我们的前路非常清晰。飞去翡翠林的东南部，到永恒岛上与我会面！', '', '', '', '', '', '', 45114),
(33087, 'zhCN', '回旅店与我会面', '到雾纱栈道迷雾酒肆的楼上与拉希奥会面。', '我敢肯定，你此刻已经迫不及待地想要试试自己的新披风了。那就让它发挥作用吧。$b$b回旅馆里与我碰面！一项新发现引起了我的注意，我们可以对其善加利用。', '', '', '', '', '', '', 45114),
(32861, 'zhCN', '善行披风', '前往雾纱栈道的石匠之愚，与拉希奥交谈。', '我们有了需要的东西。我能创造出驾驭天神之力的物品，而且只要略作努力，也许还能把我自己的部分力量收入其中。$b$b到石匠之愚上方与我会面吧，就在雾纱栈道迷雾酒肆的东边，我们曾经在那里见过面。结果会让你喜出望外的！', '', '', '', '', '', '', 45114),
(32805, 'zhCN', '天神的祝福', '前往昆莱山的白虎寺、卡桑琅丛林的朱鹤寺、翡翠林的青龙寺、螳螂高原的砮皂寺，获得四位天神的祝福。完成他们四项挑战中的其中一项。', '我愿意将自己全部的巨龙之力都赋予你，但遗憾的是，那会使你的凡人之躯彻底瓦解。不过，希望仍在——我相信我能创造出一个强大的容器来供你使用。$b$b要想制作这个容器，我需要潘达利亚四位至尊天神的祝福。与我一同前往那四座神殿吧，让我们与诸位天神谈一谈。若要让自己配得上他们的馈赠，你必须赢得他们其中一项挑战。$b$b这些挑战可不简单——选择与你的装备和技能最相匹配的挑战吧！', '', '', '', '', '', '', 45114),
(32598, 'zhCN', '清算', '在雾纱栈道的迷雾酒肆楼上与拉希奥交谈。', '雷电之王死了，他用于镇压的工具已由联盟和部落夺取，以实现自己的目的。$b$b我们现在已来到熊猫人战役的巅峰。地狱咆哮的诡计已使联盟无力应对——但更为重要的是，他还使部落变得分崩离析。正如熊猫人所说：“打铁趁热。”必须采取行动了，我们所有的努力也都是为了这个。$b$b我需要时间来制定计划。等你的阵营做好准备就来见我！', '', '', '', '', '', '去雾纱栈道迷雾酒肆的楼上找拉希奥谈一谈。', 45114),
(32597, 'zhCN', '雷神之核', '在雷电王座内殿里消灭雷电之王，并取得雷神之核。', '已死去一万两千年之久的雷电之王，却被赞达拉的声音唤了回来。无疑是泰坦之力使他邪恶的尸身恒久不腐。$b$b泰坦之力应该归我所有。$b$b$n！把雷神之核给我带回来。一旦我得到了它，谁也别想再让他起死回生。$b$b把它带来交给我，$c。把他冰冷的核心交给我！', '', '', '', '', '', '', 45114),
(32595, 'zhCN', '苍穹之冠', '与拉希奥在雾纱栈道的石匠之愚碰面，并领取奖赏。', '你还记得石匠之愚吗？就在东边的山顶上，我们曾在那里见过面。$b$b我要用这把闪电长枪创造一样特别的东西，当然不能在这进行了。$b$b去石匠之愚与我会面，让我们共同欢庆胜利！', '', '', '', '', '', '', 45114),
(32594, 'zhCN', '暴风领主之魂', '在雷神岛上继续探索，直到你找到最后一个庭院。将长枪插进暴风领主纳拉克的身体里，坚持到将他的力量虹吸出来，以获得淬火闪电长枪。', '我们的下一个目标，就是要用充满雷电之王力量的半神之血来调节这把武器。$b$b据密探回报，有位名叫山怖的魔古族正在创造这样一种怪物，想让其戍守雷电堡。$b$b当你的阵营攻到前门时，攻击暴风领主纳拉克，并将这根长枪插进它的身侧。这只怪物会使出浑身解数来阻止你——在成功将暴风领主的力量吸出来以前，千万要挺住！', '', '', '', '', '', '', 45114),
(32590, 'zhCN', '楼上的约见', '在雾纱栈道的迷雾酒肆二楼与拉希奥会面。', '我想带你见个人。暴风城的王子殿下不久前造访了这间简陋的旅舍。我命令守卫保护他，使他免受任何来自部落的威胁——当然，我可不想为自己招来任何不必要的关注。$b$b他与我纵谈世界大事，比如发生在南部海岸上的战争，他与加尔鲁什的会面，以及雷电之王即将发起的攻击。$b$b来吧！让我们到楼上聊聊……', '', '', '', '', '', '在雾纱栈道的迷雾酒肆二楼与拉希奥会面。', 45114),
(32427, 'zhCN', '领袖的标准', '与迷雾酒肆的拉希奥谈一谈。', '我们的熊猫人战役已经发展到了新的阶段。你们的酋长试图以部落的强大武力震慑熊猫人。无论熊猫人是否愿意，他都会攫取这片土地的资源。$b$b我理解你们领袖的意愿，但我更想理解酋长本人的意图。到底是什么在驱使着他？部落究竟会走向何方？我想跟你谈谈你们的这位领袖。', '', '', '', '', '', '', 45114),
(31518, 'zhCN', '锦绣谷', '去天神之门和安度因谈一谈。', '通往锦绣谷的大门上一次打开，已经是许多代人之前的事了，$n。$b$b我无论如何也不能错过这般盛事，$n！你也一样。$b$b到昆莱山南麓去见我。我会在那里等你。', '', '', '', '', '', '', 45114),
(467, 'zhCN', '迪恩·石轮的梦想', '和驾驶员迪恩·石轮谈一谈。', '驾驶员迪恩·石轮和其他驾驶员一样非常喜欢他的攻城坦克，他一直都想要找到加强坦克火力的方法！$B$B他听说有一种罕见的矿石，现在正在到处拉人为他寻找这种矿石呢。如果你想找点事干的话，就去丹莫罗的钢架补给站找他，看看他都需要些什么。', '', '', '', '', '', '', 45114),
(343, 'zhCN', '关于坚韧的演讲', '到暴风城堡的皇家图书馆去与米尔顿·西弗交谈，他将会为你找到克里斯托弗修士所需要的关于冶金学的书。', '我正要作一次关于“坚韧的灵魂”的演讲，我想引用一本关于金属学的著作《金属的延展性》里的一些段落。暴风城堡里的皇家图书馆里应该有这本书的副本。你能把它拿来给我吗？如果可以的话，圣光定会保佑你的！$B$B皇家图书馆很大，但首席管理员米尔顿·西弗对每一个书架上有些什么书都了如指掌。告诉他我需要什么，他就会把书找给你的。', '', '', '', '', '', '', 45114);

